<?php $maximoConexiones = max(array_column($conexionesPorPeriodo, 'conexiones') ?: [1]); $anteriorConexiones = null; ?>
<section class="panel mt-6"><div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="section-title">Conexiones activas importadas</h2><p class="mt-1 text-sm text-slate-500">Evolución mensual de las 36 zonas de presión incluidas en la matriz.</p></div><span class="badge"><i class="bi bi-activity" aria-hidden="true"></i> Serie histórica</span></div><div class="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-7"><?php foreach ($conexionesPorPeriodo as $periodo): $variacion = $anteriorConexiones === null ? null : (int) $periodo['conexiones'] - $anteriorConexiones; $anteriorConexiones = (int) $periodo['conexiones']; ?><article class="connection-card"><div class="flex items-center justify-between gap-2"><p class="text-xs font-semibold text-slate-500"><?= e($meses[(int) $periodo['mes']]) ?></p><i class="bi bi-diagram-3 text-brand-600" aria-hidden="true"></i></div><p class="mt-3 text-xl font-bold tracking-tight text-slate-900"><?= number_format((int) $periodo['conexiones']) ?></p><div class="mt-3 h-1.5 overflow-hidden rounded-full bg-brand-100"><span class="block h-full rounded-full bg-brand-600" style="width: <?= min(100, round(((int) $periodo['conexiones'] / $maximoConexiones) * 100)) ?>%"></span></div><p class="mt-3 text-xs text-slate-500"><?php if ($variacion === null): ?>Mes base<?php elseif ($variacion >= 0): ?><span class="font-medium text-teal-700">+<?= number_format($variacion) ?></span> vs. mes previo<?php else: ?><span class="font-medium text-rose-700"><?= number_format($variacion) ?></span> vs. mes previo<?php endif; ?></p></article><?php endforeach; ?></div></section>
